// This is a sample PHP code snippet related to automobile management systems.

function displayVehicleDetails($vehicle) {
    echo "Make: " . $vehicle['make'] . "<br>";
    echo "Model: " . $vehicle['model'] . "<br>";
    echo "Year: " . $vehicle['year'] . "<br>";
}

$vehicles = array(
    array('make' => 'Toyota', 'model' => 'Corolla', 'year' => '2019'),
    array('make' => 'Honda', 'model' => 'Civic', 'year' => '2021')
);

foreach ($vehicles as $vehicle) {
    displayVehicleDetails($vehicle);
}
?>"

